function factor(n){const r=[];for(let p=2;p*p<=n;p++){let e=0;while(n%p===0){n/=p;e++;}if(e)r.push([p,e]);}if(n>1)r.push([n,1]);return r;}
const SUP='⁰¹²³⁴⁵⁶⁷⁸⁹';const sup=e=>String(e).split('').map(c=>SUP[+c]).join('');
const fmtF=f=>f.map(([p,e])=>e>1?p+sup(e):String(p)).join(' · ');
function modpow(b,e,m){let r=1n,B=BigInt(b)%BigInt(m),E=BigInt(e);const Mm=BigInt(m);while(E>0n){if(E&1n)r=r*B%Mm;B=B*B%Mm;E>>=1n;}return Number(r);}
